<?php
require 'config/database.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: apply.php');exit;}
$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$phone=trim($_POST['phone']??'');$qualification=trim($_POST['qualification']??'');$address=trim($_POST['address']??'');$skills=trim($_POST['skills']??'');$jobId=(int)($_POST['job_id']??0);$cover=trim($_POST['cover_letter']??'');
if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6||!$jobId||!isset($_FILES['resume'])){header('Location: apply.php?error='.urlencode('Please complete all fields.'));exit;}
$ext=strtolower(pathinfo($_FILES['resume']['name'],PATHINFO_EXTENSION));$allowed=['pdf','doc','docx','jpg','jpeg','png'];if($_FILES['resume']['error']!==UPLOAD_ERR_OK||!in_array($ext,$allowed,true)||$_FILES['resume']['size']>5242880){header('Location: apply.php?error='.urlencode('Upload a PDF, DOC, DOCX, JPG, JPEG or PNG file (maximum 5 MB).'));exit;}
$conn->begin_transaction();try{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$conn->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'job_seeker')");$stmt->bind_param('sss',$name,$email,$hash);$stmt->execute();$seekerId=$conn->insert_id;$stmt=$conn->prepare('INSERT INTO job_seekers(seeker_id,phone,qualification,skills,address) VALUES(?,?,?,?,?)');$stmt->bind_param('issss',$seekerId,$phone,$qualification,$skills,$address);$stmt->execute();$fileName=$seekerId.'_'.time().'_'.preg_replace('/[^A-Za-z0-9._-]/','-',basename($_FILES['resume']['name']));$path='uploads/'.$fileName;if(!move_uploaded_file($_FILES['resume']['tmp_name'],$path))throw new Exception('Upload failed');$type=$_FILES['resume']['type'];$stmt=$conn->prepare('INSERT INTO resumes(seeker_id,file_name,file_type,file_path) VALUES(?,?,?,?)');$stmt->bind_param('isss',$seekerId,$fileName,$type,$path);$stmt->execute();$resumeId=$conn->insert_id;$stmt=$conn->prepare('INSERT INTO applications(job_id,seeker_id,resume_id,cover_letter) VALUES(?,?,?,?)');$stmt->bind_param('iiis',$jobId,$seekerId,$resumeId,$cover);$stmt->execute();$id=$conn->insert_id;$conn->commit();header('Location: tracking.php?id='.$id);exit;}catch(Throwable $e){$conn->rollback();if(isset($path)&&file_exists($path))unlink($path);header('Location: apply.php?error='.urlencode($e->getCode()===1062?'Email already exists.':$e->getMessage()));exit;}
?>
